codeExamples.code:
-- Upgrade the table to support column mapping (one-way protocol bump)
ALTER TABLE gold.orders SET TBLPROPERTIES (
  'delta.columnMapping.mode' = 'name',
  'delta.minReaderVersion' = '2',
  'delta.minWriterVersion' = '5'
);

-- Rename a column (metadata-only, instant)
ALTER TABLE gold.orders RENAME COLUMN amt TO order_amount;

-- Drop a column (metadata-only with column mapping)
ALTER TABLE gold.orders DROP COLUMN deprecated_flag;

-- Add a column with a comment
ALTER TABLE gold.orders ADD COLUMN promo_code STRING COMMENT 'optional promo';
